const salida = [];
const respuestas = $input.all();
const entradas = $('Limpiar texto').all();

for (let i = 0; i < respuestas.length; i++) {
  const correo = (entradas[i] && entradas[i].json.correo) || {};
  const respuesta = respuestas[i].json;

  const texto = respuesta.choices?.[0]?.message?.content || '';

  let datos = {};
  let error_ia = false;
  let motivo = '';
  if (respuesta.error) {
    error_ia = true;
    const detalle = typeof respuesta.error === 'string' ? respuesta.error : (respuesta.error.message || JSON.stringify(respuesta.error));
    motivo = ('Error de la IA: ' + detalle).slice(0, 300);
  } else {
    try {
      const m = texto.match(/\{[\s\S]*\}/);
      datos = JSON.parse(m ? m[0] : texto);
    } catch (e) {
      error_ia = true;
      motivo = 'No se pudo leer la respuesta de la IA';
    }
  }

  const categoria = String(datos.categoria || 'NO_ENTENDIDO').toUpperCase();
  const esReserva = ['RESERVA', 'MODIFICACION'].includes(categoria);
  const pax = datos.pax || {};
  const clientes = esReserva && Array.isArray(datos.clientes) ? datos.clientes.join(', ') : '';
  const servicios = esReserva && Array.isArray(datos.servicios) && datos.servicios.length > 0
    ? datos.servicios
    : [{}];

  let estado;
  if (categoria === 'PUBLICIDAD' || categoria === 'OTRO') {
    estado = 'sin accion';
  } else if (esReserva) {
    const primero = servicios[0] || {};
    estado = (primero.fecha_servicio || primero.hotel) ? 'pendiente de transcribir' : 'revisar';
  } else {
    estado = 'revisar';
  }

  const base = {
    categoria: categoria,
    remitente: correo.from || '',
    asunto: correo.subject || '',
    estado: estado,
    fecha: correo.date || '',
    cuerpo: correo.textPlain || '',
    message_id: correo.metadata?.['message-id'] || '',
    buzon: 'serviciosintegraleskaizen.ia@gmail.com',
    agencia: esReserva ? (datos.agencia || '') : '',
    nombre_cliente: clientes,
    telefono: datos.telefono || '',
    adultos: esReserva ? (Number(pax.adultos) || 0) : 0,
    ninos: esReserva ? (Number(pax.ninos) || 0) : 0,
    infantes: esReserva ? (Number(pax.infantes) || 0) : 0,
    error_ia: error_ia,
    motivo: motivo
  };

  servicios.forEach((s, n) => {
    salida.push({
      json: {
        ...base,
        numero_servicio: n + 1,
        tipo_servicio: s.tipo_servicio || '',
        actividad: s.actividad || '',
        aeropuerto: s.aeropuerto || datos.aeropuerto || '',
        fecha_servicio: s.fecha_servicio || '',
        hora_servicio: s.hora_servicio || '',
        vuelo: s.vuelo || '',
        hotel: s.hotel || '',
        punto_partida: s.punto_partida || '',
        punto_llegada: s.punto_llegada || ''
      }
    });
  });
}

return salida;

const correos = $('Traducir correo').all().map(x => x.json);

return $input.all().map(item => {
  const correo = correos.find(c => c.metadata['message-id'] === item.json.message_id) || {};
  const dominio = ((correo.from || '').match(/@([^>\s]+)/) || [])[1] || '';
  const recibido = new Date(correo.date);
  const fechaRecibido = isNaN(recibido) ? '' : recibido.toISOString().slice(0, 10);
  const instruccion = `Clasifica este correo en una categoria: RESERVA, MODIFICACION, SEGUIMIENTO, CONSULTA, PUBLICIDAD, FACTURA, OTRO, NO_ENTENDIDO. RESERVA es una solicitud de servicio nueva. MODIFICACION es un cambio a una reserva ya enviada (cambiar fecha, hora, hotel, pasajeros o cancelar). Si el correo es un reenvio (Fwd, RV, Reenviado), clasifica el mensaje original que viene dentro. Devuelve solo JSON valido, sin texto extra. Formato: {"categoria": "...", "agencia": "...", "clientes": [], "pax": {"adultos": 0, "ninos": 0, "infantes": 0}, "aeropuerto": "", "servicios": []}. Regla: si la categoria es RESERVA o MODIFICACION, llena agencia, clientes, pax, aeropuerto y servicios con los datos del correo (en MODIFICACION usa los datos nuevos). Para agencia: escribe SOLO el nombre de la empresa de viajes. Nunca pongas el nombre de una persona ni el nombre del remitente. Busca el nombre de la empresa en la firma o el pie de pagina escritos; si el dominio no es gmail, hotmail, yahoo u outlook, puedes usarlo. Si no encuentras el nombre de la empresa, deja agencia vacia. Si la categoria es otra, deja agencia en blanco, clientes vacio, pax en 0 y servicios vacio. Para RESERVA y MODIFICACION llena servicios con tipo_servicio, actividad, aeropuerto, hora_servicio, fecha_servicio, vuelo, hotel, punto_partida, punto_llegada. Formatos obligatorios: fecha_servicio en AAAA-MM-DD (si el correo no trae el año, usa el año de la fecha de recibido, o el siguiente si esa fecha ya paso; en hotel usa la fecha de entrada); hora_servicio en HH:MM de 24 horas; aeropuerto en codigo IATA de 3 letras (PUJ, SDQ, LRM, POP, STI) solo si el correo lo dice. Si hay hotel o fechas en el texto, llenalos dentro de servicios aunque el servicio no tenga actividad. Ignora el bloque de Vision general creada por IA y los textos de firma o confidencialidad. Si la informacion de vuelos esta solo en una imagen, deja vuelo vacio. Responde directamente con el JSON, sin razonar en voz alta. Fecha de recibido: ${fechaRecibido}. Dominio del remitente: ${dominio}. Correo: `;
  const texto = String(correo.textPlain || '').replace(/\s+/g, ' ').slice(0, 4000);
  return {
    json: {
      body: {
        model: "nvidia/nemotron-3.5-super-vl:free",
        max_tokens: 4000,
        messages: [{ role: "user", content: instruccion + texto }]
      },
      dominio: dominio,
      correo: correo
    }
  };
});

function decodificar(s) {
  return String(s || '')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&#x27;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function textoPlano(parte) {
  if (!parte) return '';
  if (parte.mimeType === 'text/plain' && parte.body && parte.body.data) {
    return Buffer.from(parte.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
  }
  for (const p of (parte.parts || [])) {
    const t = textoPlano(p);
    if (t) return t;
  }
  return '';
}

function htmlATexto(html) {
  return String(html || '')
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
}

return $input.all().map(item => {
  const j = item.json;
  const cabeceras = (j.payload && j.payload.headers) || [];
  const leer = (nombre) => {
    const h = cabeceras.find(x => x.name && x.name.toLowerCase() === nombre.toLowerCase());
    if (h) return h.value;
    const directo = j[nombre] || j[nombre.toLowerCase()];
    if (directo && typeof directo === 'object') return directo.text || '';
    return directo || '';
  };
  const fecha = leer('Date') || (j.internalDate ? new Date(Number(j.internalDate)).toISOString() : '');
  const texto = j.text || textoPlano(j.payload) || htmlATexto(j.html) || j.snippet || '';
  return {
    json: {
      metadata: { 'message-id': j.id },
      from: decodificar(leer('From')),
      subject: decodificar(leer('Subject')),
      date: fecha,
      textPlain: decodificar(texto)
    }
  };
});
